import { describe, expect, it } from "vitest";
import { renderCiFixWorkflow } from "../../src/workflow-template.js";

describe("workflow generator", () => {
  it("renders the baseline workflow (snapshot)", () => {
    expect(renderCiFixWorkflow({ monitoredWorkflows: ["CI"] })).toMatchInlineSnapshot(`
      "# Generated by \`alran ci init\`. Re-run \`alran ci init\` to change this file.
      name: Alran CI Fix
      on:
        workflow_run:
          workflows:
            - "CI"
          types:
            - completed
      permissions:
        contents: write
        pull-requests: write
        actions: read
      jobs:
        alran-ci-fix:
          # Forks are never fixed: the failing run must come from this repository.
          if: >-
            github.event.workflow_run.conclusion == 'failure' &&
            github.event.workflow_run.head_repository.full_name == github.repository
          runs-on: ubuntu-latest
          steps:
            - name: Check out the failing head commit
              uses: actions/checkout@v4
              with:
                ref: \${{ github.event.workflow_run.head_sha }}
            - name: Set up Node.js
              uses: actions/setup-node@v4
              with:
                node-version: 22
            - name: Install Alran Code
              run: npm install -g alran
            - name: Reproduce, fix, verify and report
              env:
                ALRAN_API_KEY: \${{ secrets.ALRAN_API_KEY }}
                ALRAN_CI_PUSH_TOKEN: \${{ secrets.ALRAN_CI_PUSH_TOKEN }}
                ALRAN_CI_RUN_ID: \${{ github.event.workflow_run.id }}
                GITHUB_TOKEN: \${{ secrets.GITHUB_TOKEN }}
              run: alran ci fix --workflow-run
      "
    `);
  });

  it("renders every monitored workflow name", () => {
    const yaml = renderCiFixWorkflow({ monitoredWorkflows: ["CI", "Node CI", "Rust"] });
    expect(yaml).toContain('- "CI"');
    expect(yaml).toContain('- "Node CI"');
    expect(yaml).toContain('- "Rust"');
  });

  it("never uses pull_request_target and checks out the head sha", () => {
    const yaml = renderCiFixWorkflow({ monitoredWorkflows: ["CI"] });
    expect(yaml).not.toContain("pull_request_target");
    expect(yaml).toContain("workflow_run:");
    expect(yaml).toContain("github.event.workflow_run.head_sha");
    expect(yaml).toContain("github.event.workflow_run.head_repository.full_name == github.repository");
    expect(yaml).toContain("github.event.workflow_run.conclusion == 'failure'");
  });

  it("declares exactly the minimal permission set", () => {
    const yaml = renderCiFixWorkflow({ monitoredWorkflows: ["CI"] });
    const permissions = yaml.split("permissions:\n")[1]?.split("\njobs:")[0] ?? "";
    expect(permissions).toContain("contents: write");
    expect(permissions).toContain("pull-requests: write");
    expect(permissions).toContain("actions: read");
    expect(permissions.trim().split("\n")).toHaveLength(3);
  });

  it("keeps the fix command overridable", () => {
    const yaml = renderCiFixWorkflow({
      monitoredWorkflows: ["CI"],
      fixCommand: "alran ci fix --workflow-run --verbose",
    });
    expect(yaml).toContain("run: alran ci fix --workflow-run --verbose");
  });

  it("falls back to the CI workflow when none are named", () => {
    expect(renderCiFixWorkflow({ monitoredWorkflows: [] })).toContain('- "CI"');
  });
});
